import { gameConfigRows } from "@config/game";

/** SQL upserting public.game_config from config/game.ts (generated file). */
export function renderGameConfigSeed(): string {
  const rows = Object.entries(gameConfigRows()).map(([key, value]) => {
    const json = JSON.stringify(value).replaceAll("'", "''");
    return `  ('${key}', '${json}'::jsonb)`;
  });
  return [
    "-- GENERATED by `pnpm config:generate` from config/game.ts. Do not edit by hand.",
    "insert into public.game_config (key, value) values",
    rows.join(",\n"),
    "on conflict (key) do update set value = excluded.value, updated_at = now();",
    "",
  ].join("\n");
}
